R = []
R.append((7684396,
("Chow mein de pollo",
 "Nuestra versión más saludable de este clásico es baja en grasa saturada, azúcar y sal, y le aporta dos de sus cinco porciones diarias.",
 ["1 cucharada de aceite de girasol", "1 cebolla, partida por la mitad y en rodajas finas", "2 pechugas de pollo (300 g), cortadas en tiras de 4 cm de largo", "1 zanahoria, cortada en bastoncitos de 2 cm de largo", "125 g de hongos shiitake", "1 calabacín, cortado en bastones", "100 g de habas de soya (edamame) congeladas frescas, descongeladas", "2 cucharaditas de cinco especias chinas", "2 cucharaditas de salsa de soya reducida en sal", "2 dientes de ajo, machacados", "1 paquete de 300 g de fideos de huevo precocidos"],
 ["Ponga el aceite de girasol en una olla grande o wok, luego añada la cebolla y cocine 2 minutos.", "Luego añada el pollo y revuelva constantemente de 3 a 4 minutos, cuidando que los trozos no se peguen entre sí.", "Añada las zanahorias, los hongos y el calabacín. Cocine de 3 a 4 minutos más, revolviendo de nuevo constantemente.", "Luego añada las habas de soya, las cinco especias chinas, la salsa de soya, el ajo y los fideos.", "Mezcle bien otros 3 a 4 minutos, hasta que los fideos estén calientes por completo."],
 ["Para una alternativa sin gluten, use fideos de arroz y tamari sin gluten.", "Puede cambiar las habas de soya por garbanzos o ejotes congelados.", "Para una versión vegetariana, use trozos de tofu marinado en lugar de pollo.", "Esta receta también queda bien con pavo en lugar de pollo.", "Los hongos shiitake son un potenciador natural del sabor y mucho más saludables que el glutamato monosódico que se usa en muchas comidas chinas para llevar."]),
("تشاو مين بالدجاج",
 "نسختنا الأكثر صحة من هذا الطبق الكلاسيكي قليلة الدهون المشبعة والسكر والملح، وتمنحك حصتين من خمس حصص يوميًا.",
 ["1 ملعقة كبيرة من زيت دوار الشمس", "1 بصلة، مقسومة إلى نصفين ومقطعة شرائح رفيعة", "2 صدر دجاج (300 غرام)، ممزقة إلى شرائح بطول 4 سم", "1 جزرة، مقطعة أعوادًا رفيعة بطول 2 سم", "125 غرامًا من فطر الشيتاكي", "1 كوسا، مقطعة أعوادًا", "100 غرام من فول الصويا (الإدامامي) الطازج المجمد، مذاب التجمد", "2 ملعقة صغيرة من خمس بهارات صينية", "2 ملعقة صغيرة من صلصة الصويا قليلة الملح", "2 فص ثوم، مهروسة", "1 عبوة 300 غرام من نودلز البيض المطبوخة مسبقًا"],
 ["ضع زيت دوار الشمس في قدر كبيرة أو مقلاة ووك، ثم أضف البصل واطهه دقيقتين.", "بعد ذلك أضف الدجاج وقلّب باستمرار من 3 إلى 4 دقائق مع التأكد من عدم التصاق القطع ببعضها.", "أضف الجزر والفطر والكوسا. اطهها من 3 إلى 4 دقائق إضافية مع التحريك المستمر أيضًا.", "بعد ذلك أضف فول الصويا والبهارات الصينية الخمسة وصلصة الصويا والثوم والنودلز.", "اخلط جيدًا من 3 إلى 4 دقائق أخرى حتى تسخن النودلز تمامًا."],
 ["للحصول على بديل خالٍ من الغلوتين، استخدم نودلز الأرز وصلصة التاماري الخالية من الغلوتين.", "يمكنك استبدال فول الصويا بالحمص أو الفاصوليا الخضراء المجمدة.", "للحصول على نسخة نباتية، استخدم قطع التوفو المتبّل بدلًا من الدجاج.", "تصلح هذه الوصفة أيضًا مع الديك الرومي بدلًا من الدجاج.", "فطر الشيتاكي معزز طبيعي للنكهة وأكثر صحة بكثير من غلوتامات أحادية الصوديوم المستخدمة في كثير من المأكولات الصينية الجاهزة."])))
R.append((7688306,
("Gazpacho",
 "Una sopa baja en calorías que resulta una excelente entrada de verano o un almuerzo ligero de verano.",
 ["750 g de tomates maduros, picados grueso", "300 ml de pasata o jugo de tomate", "2 cucharadas de vinagre de vino tinto", "1 cucharada de aceite de oliva", "unas gotas de Tabasco (opcional)", "1 cebolla morada, finamente picada", "medio pepino, picado en trozos pequeños", "1 pimiento verde, sin semillas y finamente picado", "1 manojo grande de albahaca fresca, desgarrada", "pimienta negra recién molida", "cubos de hielo, para servir"],
 ["Ponga la mitad de los tomates en un procesador de alimentos o licuadora junto con la pasata, el vinagre, el aceite, el azúcar y el Tabasco (si lo usa). Licue hasta que quede suave; si la mezcla queda algo espesa, añada un poco más de jugo de tomate.", "Incorpore el resto de los ingredientes, añada unos cubos de hielo y sirva."],
 []),
("غازباتشو",
 "شوربة قليلة السعرات الحرارية تصلح مقبلات صيفية رائعة أو وجبة غداء صيفية خفيفة.",
 ["750 غرامًا من الطماطم الناضجة، مفرومة فرمًا خشنًا", "300 مل من صلصة الطماطم المصفاة (باساتا) أو عصير الطماطم", "2 ملعقة كبيرة من خل النبيذ الأحمر", "1 ملعقة كبيرة من زيت الزيتون", "بضع قطرات من صلصة تاباسكو (اختياري)", "1 بصلة حمراء، مفرومة ناعمًا", "نصف خيارة، مقطعة قطعًا صغيرة", "1 حبة فلفل رومي أخضر، منزوعة البذور ومفرومة ناعمًا", "حزمة كبيرة من الريحان الطازج، ممزقة", "فلفل أسود مطحون طازجًا", "مكعبات ثلج، للتقديم"],
 ["ضع نصف كمية الطماطم في معالج طعام أو خلاط مع الباساتا والخل والزيت والسكر وصلصة التاباسكو (إن استخدمتها). امزجها حتى تصبح ناعمة، وإذا كان الخليط سميكًا قليلًا فأضف المزيد من عصير الطماطم.", "أضف بقية المكونات وقلّب، وأضف بضع مكعبات ثلج وقدّم."],
 [])))
R.append((7690806,
("Tiras de lenguado empanizadas con chips de verduras",
 "Pruebe este plato como una sabrosa alternativa a las papas fritas. La polenta le da una cubierta crujiente y muy sabrosa, mucho más saludable que un rebozado.",
 ["2 papas medianas (aprox. 200 g cada una), cortadas en bastones gruesos", "1 camote, pelado y cortado en bastones gruesos", "1 chirivía, pelada y cortada en bastones gruesos", "2 cucharaditas de aceite de oliva", "1 cucharada de perejil picado", "50 g de polenta (harina de maíz)", "1 diente de ajo, machacado", "ralladura de 1 lima", "pimienta negra recién molida", "2 filetes de lenguado limón o platija sin piel, de unos 150 g cada uno, cortados en tiras gruesas", "1 huevo, batido"],
 ["Precaliente el horno a 200 ºC (gas 6). Ponga las papas, el camote y la chirivía en una olla con agua hirviendo y cocine 5 minutos.", "Escurra y coloque en una fuente para asar; rocíe con la mitad del aceite.", "Hornee de 25 a 30 minutos, hasta que estén doradas y tiernas. Mezcle el perejil, la polenta, el ajo y la ralladura de lima en un tazón bastante plano y sazone con la pimienta negra.", "Pase los trozos de lenguado por el huevo batido y luego por la mezcla de polenta para cubrirlos.", "Caliente el aceite restante en una sartén antiadherente, añada los trozos de pescado empanizados y fría 2 minutos por cada lado, hasta que estén dorados y crujientes.", "Sirva con las chips de verduras y una ensalada verde fresca."],
 ["Puede usar esta cubierta con tiras de bacalao, eglefino, bagre de río o tilapia.", "También puede preparar la receta con tiras de pollo o pavo.", "Instrucciones para congelar: Cocine, enfríe de inmediato y congele sobre una bandeja para hornear. Una vez congelado, colóquelo con cuidado en bolsas por porciones para usarlo. Recaliente bien hasta que esté muy caliente."]),
("أصابع سمك موسى المقرمشة مع رقائق الخضار",
 "جرّب هذا الطبق كبديل لذيذ للبطاطس المقلية. تمنح البولينتا طبقة خارجية مقرمشة ولذيذة جدًا، وهي أكثر صحة بكثير من العجينة السائلة.",
 ["2 حبة بطاطس متوسطة (حوالي 200 غرام لكل منها)، مقطعة أصابع سميكة", "1 حبة بطاطا حلوة، مقشرة ومقطعة أصابع سميكة", "1 جزرة بيضاء (باستنج)، مقشرة ومقطعة أصابع سميكة", "2 ملعقة صغيرة من زيت الزيتون", "1 ملعقة كبيرة من البقدونس المفروم", "50 غرامًا من البولينتا (دقيق الذرة)", "1 فص ثوم، مهروس", "قشر 1 ليمونة خضراء مبشور", "فلفل أسود مطحون طازجًا", "2 فيليه من سمك موسى الليموني أو البلايس بدون جلد، حوالي 150 غرامًا لكل منهما، مقطعة شرائح سميكة", "1 بيضة، مخفوقة"],
 ["سخّن الفرن مسبقًا إلى 200° مئوية (علامة الغاز 6). ضع البطاطس والبطاطا الحلوة والجزر الأبيض في قدر من الماء المغلي واطهها 5 دقائق.", "صفِّها وضعها في صينية تحميص ثم رشّ نصف الزيت فوقها.", "ضعها في الفرن واخبزها من 25 إلى 30 دقيقة حتى تصبح ذهبية وطرية. اخلط البقدونس والبولينتا والثوم وقشر الليمون الأخضر في وعاء مسطح نوعًا ما، وتبّل بالفلفل الأسود.", "اغمس قطع سمك موسى في البيض المخفوق ثم في خليط البولينتا لتغطيتها.", "سخّن بقية الزيت في مقلاة غير لاصقة، وأضف قطع السمك المغطاة وقلّها دقيقتين على كل جانب حتى تصبح ذهبية ومقرمشة.", "قدّمها مع رقائق الخضار وسلطة خضراء طازجة."],
 ["يمكنك استخدام هذه الطبقة على شرائح سمك القد أو الحدوق أو سمك الكوبلر النهري أو البلطي.", "يمكنك أيضًا تحضير الوصفة بشرائح من الدجاج أو الديك الرومي.", "تعليمات التجميد: اطهها ثم برّدها فورًا وجمّدها على صينية خبز. وبعد تجمدها ضعها بعناية في أكياس حسب الحصص للاستخدام. أعد تسخينها جيدًا حتى تصبح ساخنة تمامًا."])))
R.append((7692699,
("Pizzetas de pan de soda",
 "Estas deliciosas mini pizzas siempre tienen éxito y son perfectas para cualquier fiesta.",
 ["2 tomates frescos, en rodajas finas", "1 cebolla morada, en rodajas muy finas", "100 g de elote (maíz dulce)", "50 g de mozzarella reducida en grasa, en rebanadas finas", "125 g de harina integral y un poco más para espolvorear al extender", "media cucharadita de bicarbonato de sodio", "1 cucharada de yogur", "1 cucharadita de aceite de colza", "1 cucharada de puré de tomate", "1 cucharadita colmada de orégano"],
 ["Precaliente el horno a 190 °C (gas 5). Prepare todas las verduras y corte el queso en rebanadas para la cobertura.", "Ponga la harina y el bicarbonato de sodio en un tazón.", "Incorpore bien el yogur y 75 ml de agua. Forme ocho bolitas y extiéndalas en círculos, usando un poco de harina para evitar que se peguen.", "Colóquelas en una bandeja para hornear ligeramente engrasada y úntelas con el puré de tomate; luego añada una rodaja de tomate y espolvoree con orégano. Esparza la cebolla y el elote y cubra cada una con una rebanada de mozzarella.", "Hornee 10 minutos y sirva."],
 ["Puede usar la cobertura que prefiera: pruebe con espinaca, pimiento rojo y cebolla, o use queso Cheddar reducido en grasa en lugar de mozzarella.", "Haga cada pizzeta de la mitad de tamaño para obtener bocadillos perfectos para fiestas.", "Instrucciones para congelar: Se puede congelar una vez cocida. Congele con papel encerado entre cada pizzeta. Descongele 1 hora y luego hornee como de costumbre."]),
("بيتزيتا بخبز الصودا",
 "هذه البيتزا المصغرة اللذيذة تحظى دائمًا بالإعجاب وهي مثالية لأي حفلة.",
 ["2 حبة طماطم طازجة، مقطعة شرائح رفيعة", "1 بصلة حمراء، مقطعة شرائح رفيعة جدًا", "100 غرام من الذرة الحلوة", "50 غرامًا من جبن الموزاريلا قليل الدسم، مقطعًا شرائح رفيعة", "125 غرامًا من دقيق القمح الكامل مع قليل منه للرش عند الفرد", "نصف ملعقة صغيرة من بيكربونات الصوديوم", "1 ملعقة كبيرة من الزبادي", "1 ملعقة صغيرة من زيت اللفت (الكانولا)", "1 ملعقة كبيرة من معجون الطماطم", "1 ملعقة صغيرة مكدسة من الأوريغانو"],
 ["سخّن الفرن مسبقًا إلى 190° مئوية (علامة الغاز 5). جهّز جميع الخضار وقطّع الجبن إلى شرائح للإضافات.", "ضع الدقيق وبيكربونات الصوديوم في وعاء خلط.", "أضف الزبادي و75 مل من الماء واخلط جيدًا. شكّل ثماني كرات صغيرة وافردها على شكل أقراص، مستخدمًا قليلًا من الدقيق لمنع الالتصاق.", "ضعها على صينية خبز مدهونة بقليل من الزيت وادهنها بمعجون الطماطم ثم أضف شريحة طماطم ورشّ الأوريغانو. انثر البصل والذرة وغطِّ كل واحدة بشريحة موزاريلا.", "اخبزها 10 دقائق وقدّم."],
 ["يمكنك استخدام أي إضافات تحبها، جرّب السبانخ والفلفل الرومي الأحمر والبصل، أو استخدم جبن الشيدر قليل الدسم بدلًا من الموزاريلا.", "اجعل كل بيتزيتا بنصف الحجم للحصول على لقيمات مثالية للحفلات.", "تعليمات التجميد: تصلح للتجميد بعد الطهي. جمّدها مع وضع ورق الزبدة بين كل بيتزيتا. اتركها تذوب ساعة واحدة ثم اخبزها كالمعتاد."])))
R.append((7693850,
("Pizza de coliflor",
 "Una deliciosa pizza sin gluten preparada con base de coliflor y cubierta con muchas verduras.",
 ["1 coliflor", "1 cucharadita de aceite de colza", "75 g de cebolla morada, en rodajas finas", "150 g de pimiento rojo, en rodajas finas", "150 g de calabacín, en cubos", "2 tomates frescos, picados", "2 dientes de ajo, machacados", "1 cucharadita colmada de orégano seco", "1 huevo, batido", "15 g de queso parmesano, finamente rallado", "50 g de mozzarella reducida en grasa, en rebanadas finas", "de 6 a 8 hojas de albahaca fresca, desgarradas", "media cucharadita de hojuelas de chile (opcional)"],
 ["Precaliente el horno a 180 °C (gas 4). Quite los tallos de la coliflor, divídala en trozos grandes y rállela a mano o procésela en un procesador de alimentos.", "Ponga la coliflor en un tazón, cubra con envoltura plástica y perfore la envoltura un par de veces. Cocine en el microondas a máxima potencia de 4 a 5 minutos. Deje enfriar.", "Una vez que esté completamente fría, coloque la coliflor sobre un paño de cocina limpio y exprima sobre el fregadero para quitar el exceso de agua.", "Mientras tanto, prepare la cobertura de la pizza. Caliente el aceite en una sartén y fría la cebolla, el pimiento rojo y el calabacín de 4 a 5 minutos, hasta que empiecen a dorarse. Añada los tomates, el ajo y el orégano y cocine otros 2 minutos. Mezcle bien y reserve.", "Ponga la coliflor en un tazón con el huevo y el parmesano. Mezcle bien.", "Forre una bandeja redonda para hornear o una charola para pizza de aproximadamente 25 cm de diámetro con papel para hornear antiadherente. Extienda la coliflor sobre ella hasta un grosor de ¾ cm. Hornee 15 minutos, retire del horno y cubra con las verduras y las rebanadas de mozzarella. Hornee 10 minutos más. Sirva espolvoreada con las hojas de albahaca y las hojuelas de chile, si las usa."],
 ["Si no tiene microondas, cocine la coliflor al vapor, en el paso 2, durante 2 minutos.", "Añada un poco de chile fresco finamente picado a las verduras, en el paso 4, para darle un toque realmente picante.", "En cualquier pizza, si cocina primero las verduras y luego las añade a la base, puede poner más verduras en su pizza."]),
("بيتزا القرنبيط",
 "بيتزا لذيذة خالية من الغلوتين مصنوعة بقاعدة من القرنبيط ومغطاة بالكثير من الخضار.",
 ["1 رأس قرنبيط", "1 ملعقة صغيرة من زيت اللفت (الكانولا)", "75 غرامًا من البصل الأحمر، مقطعًا شرائح رفيعة", "150 غرامًا من الفلفل الرومي الأحمر، مقطعًا شرائح رفيعة", "150 غرامًا من الكوسا، مقطعة مكعبات", "2 حبة طماطم طازجة، مفرومة", "2 فص ثوم، مهروسة", "1 ملعقة صغيرة مكدسة من الأوريغانو المجفف", "1 بيضة، مخفوقة", "15 غرامًا من جبن البارميزان، مبشورًا ناعمًا", "50 غرامًا من جبن الموزاريلا قليل الدسم، مقطعًا شرائح رفيعة", "من 6 إلى 8 أوراق ريحان طازجة، ممزقة", "نصف ملعقة صغيرة من رقائق الفلفل الحار (اختياري)"],
 ["سخّن الفرن مسبقًا إلى 180° مئوية (علامة الغاز 4). انزع سيقان القرنبيط وقسّمه إلى قطع كبيرة ثم أبشره باليد أو اطحنه في معالج الطعام.", "ضع القرنبيط في وعاء وغطِّه بغلاف بلاستيكي وثقب الغلاف مرتين. سخّنه في المايكرويف على أعلى قدرة من 4 إلى 5 دقائق. اتركه يبرد.", "بعد أن يبرد تمامًا، ضع القرنبيط على منشفة مطبخ نظيفة واعصره فوق المغسلة للتخلص من الماء الزائد.", "في الأثناء، حضّر إضافات البيتزا. سخّن الزيت في مقلاة وقلّب البصل والفلفل الرومي الأحمر والكوسا من 4 إلى 5 دقائق حتى تبدأ بالاحمرار. أضف الطماطم والثوم والأوريغانو واطهها دقيقتين إضافيتين. اخلط جيدًا وضعه جانبًا.", "ضع القرنبيط في وعاء مع البيض والبارميزان. اخلط جيدًا.", "بطّن صينية خبز مستديرة أو صينية بيتزا بقطر 25 سم تقريبًا بورق خبز غير لاصق. افرد القرنبيط عليها بسمك ¾ سم. اخبزها 15 دقيقة، ثم أخرجها من الفرن وغطِّها بالخضار وشرائح الموزاريلا. اخبزها 10 دقائق إضافية. قدّمها مرشوشة بأوراق الريحان ورقائق الفلفل الحار إن استخدمتها."],
 ["إذا لم يكن لديك مايكرويف، فاطه القرنبيط على البخار، في الخطوة 2، لمدة دقيقتين.", "أضف بعض الفلفل الحار الطازج المفروم ناعمًا إلى الخضار، في الخطوة 4، لإضفاء حرارة أكبر.", "مع أي بيتزا، إذا طهوت الخضار أولًا ثم أضفتها إلى القاعدة فيمكنك وضع كمية أكبر منها على البيتزا."])))
R.append((7695929,
("Arroz frito con pollo",
 "Una cena rápida y fácil que puede preparar en menos de 30 minutos. Con una combinación de pollo jugoso y variedad de verduras, este salteado le dará sabor a cualquier comida. Esta receta fue seleccionada en colaboración con Slimming World.",
 ["200 g de arroz basmati seco", "4 cucharadas de salsa de soya reducida en sodio o tamari", "Jugo de 2 limas", "1 trozo de 2 cm de raíz de jengibre fresco, pelado y rallado", "2 dientes de ajo, machacados", "2 chiles rojos: 1 sin semillas y finamente picado, 1 finamente rebanado, para servir", "Aceite en aerosol para cocinar, bajo en calorías", "1 cebolla morada, en rodajas", "2 pimientos rojos, sin semillas y en rodajas finas", "4 pechugas de pollo sin piel y sin hueso, en cubos", "¼ de col de Saboya, finamente rallada", "150 g de chícharos chinos", "1 lata de 225 g de castañas de agua, escurridas y enjuagadas", "4 cebollas verdes, en rodajas finas"],
 ["Cocine el arroz según las instrucciones del paquete, luego escurra y extienda sobre una bandeja para hornear antiadherente para que se enfríe rápidamente.", "Mientras el arroz se enfría, mezcle la salsa de soya o tamari, el jugo de lima, el jengibre, el ajo y el chile picado, y reserve.", "Al mismo tiempo, rocíe un wok o una sartén grande antiadherente con un par de pulverizaciones de aceite en aerosol bajo en calorías y colóquelo a fuego medio-alto. Añada la cebolla y los pimientos y saltee de 3 a 4 minutos. Añada el pollo y la col y cocine de 3 a 4 minutos más, o hasta que el pollo esté bien cocido y no se vea carne rosada (los jugos deben salir claros al cortar la parte más gruesa del pollo).", "Cuando el pollo esté casi cocido, incorpore los chícharos chinos, las castañas de agua, la mitad de las cebollas verdes y toda la mezcla de salsa de soya. Saltee unos minutos y luego empuje todo hacia un lado de la sartén. Vierta el arroz en el lado vacío y fría 2 minutos; luego mezcle todo y saltee hasta que el arroz esté muy caliente. Esparza el resto de las cebollas verdes y el chile en rodajas para servir."],
 ["Use arroz basmati integral para aumentar la fibra."]),
("أرز مقلي بالدجاج",
 "وجبة عشاء سريعة وسهلة يمكنك تحضيرها في أقل من 30 دقيقة. بمزيج من الدجاج الطري ومجموعة متنوعة من الخضار، ستضفي هذه الوجبة المقلية نكهة على أي وجبة. تم اختيار هذه الوصفة بالشراكة مع Slimming World.",
 ["200 غرام من أرز بسمتي جاف", "4 ملاعق كبيرة من صلصة الصويا قليلة الصوديوم أو التاماري", "عصير 2 ليمونة خضراء", "1 قطعة بطول 2 سم من جذر الزنجبيل الطازج، مقشرة ومبشورة", "2 فص ثوم، مهروسة", "2 حبة فلفل حار أحمر: 1 منزوعة البذور ومفرومة ناعمًا، و1 مقطعة شرائح رفيعة للتقديم", "بخاخ طهي منخفض السعرات", "1 بصلة حمراء، مقطعة شرائح", "2 حبة فلفل رومي أحمر، منزوعة البذور ومقطعة شرائح رفيعة", "4 صدور دجاج بدون جلد ولا عظم، مقطعة مكعبات", "¼ ملفوف سافوي، مقطع شرائح رفيعة", "150 غرامًا من البازلاء السكرية (مانجتو)", "1 علبة 225 غرامًا من كستناء الماء، مصفّاة ومشطوفة", "4 حبات بصل أخضر، مقطعة شرائح رفيعة"],
 ["اطبخ الأرز حسب تعليمات العبوة، ثم صفِّه وافرده على صينية خبز غير لاصقة ليبرد بسرعة.", "بينما يبرد الأرز، اخلط صلصة الصويا أو التاماري وعصير الليمون الأخضر والزنجبيل والثوم والفلفل الحار المفروم وضعه جانبًا.", "في الوقت نفسه، رشّ ووك أو مقلاة كبيرة غير لاصقة بضغطتين من بخاخ الطهي المنخفض السعرات وضعها على نار متوسطة إلى عالية. أضف البصل والفلفل الرومي وقلّب من 3 إلى 4 دقائق. أضف الدجاج والملفوف واطهها من 3 إلى 4 دقائق إضافية، أو حتى ينضج الدجاج تمامًا ولا يظهر أي لحم وردي (يجب أن تخرج العصارة صافية عند قطع أسمك جزء من الدجاج).", "عندما يكاد الدجاج ينضج، أضف البازلاء السكرية وكستناء الماء ونصف كمية البصل الأخضر وكامل خليط صلصة الصويا. قلّب بضع دقائق، ثم ادفع كل شيء إلى جانب واحد من المقلاة. ضع الأرز في الجانب الفارغ واقلِه دقيقتين، ثم اخلط كل شيء معًا وقلّب حتى يسخن الأرز تمامًا. انثر بقية البصل الأخضر والفلفل الحار المقطع للتقديم."],
 ["استخدم أرز بسمتي بنيًا لزيادة الألياف."])))
R.append((7696162,
("Mermelada de frambuesa",
 "Las frutas rojas dan una deliciosa mermelada de textura gelatinosa que a todos les encantará.",
 ["200 ml de agua", "1 sobre de gelatina de frambuesa sin azúcar en polvo", "3 cucharaditas de edulcorante granulado", "150 g de frambuesas congeladas"],
 ["Ponga el agua y la gelatina en una jarra, incorpore el edulcorante y luego añada la mitad de las frambuesas. Aplástelas suavemente con un tenedor para deshacerlas.", "Incorpore el resto de las frambuesas y luego coloque en un frasco o recipiente hermético en el refrigerador hasta que cuaje.", "Conserve en el refrigerador; dura 5 días."],
 ["Este método funciona bien con otras frutas, como fresas o zarzamoras.", "Usar fruta congelada hará que la gelatina se enfríe y cuaje más rápido que con fruta fresca.", "Para una versión vegetariana o vegana, use un agente gelificante a base de algas sin sabor y use refresco concentrado sin azúcar y edulcorante para preparar un líquido de fruta.", "Corte la mermelada con una cuchara antes de comerla para que sea más fácil de untar."]),
("مربى الفاكهة بالتوت الأحمر (الراسبيري)",
 "تُنتج الفواكه الحمراء مربى لذيذًا يشبه الجيلي سيحبه الجميع.",
 ["200 مل من الماء", "1 كيس من بلورات جيلي التوت الأحمر الخالي من السكر", "3 ملاعق صغيرة من المُحلّي الحبيبي", "150 غرامًا من التوت الأحمر المجمد"],
 ["ضع الماء والجيلي في إبريق، وأضف المُحلّي وقلّب، ثم أضف نصف كمية التوت. اهرسه برفق بالشوكة لتفتيته.", "أضف بقية التوت وقلّب، ثم ضعه في برطمان أو علبة محكمة الإغلاق في الثلاجة حتى يتماسك.", "احفظه في الثلاجة، ويبقى صالحًا 5 أيام."],
 ["تنجح هذه الطريقة جيدًا مع فواكه أخرى مثل الفراولة أو التوت الأسود.", "استخدام الفاكهة المجمدة يجعل الجيلي يبرد ويتماسك أسرع مما يحدث مع الفاكهة الطازجة.", "للحصول على نسخة نباتية، استخدم مادة تكثيف مصنوعة من الأعشاب البحرية غير منكهة، واستخدم شراب مركّز خالٍ من السكر ومُحلّيًا لتحضير سائل الفاكهة.", "قطّع المربى بالملعقة قبل تناوله ليسهل دهنه."])))
R.append((7696438,
("Ensalada de trigo bulgur con tomates y pimientos asados",
 "El trigo bulgur es una excelente base para ensaladas y es rápido y sencillo de preparar.",
 ["100 g de trigo bulgur", "450 g de tomates cherry", "1 pimiento rojo, cortado en trozos", "2 cucharadas de aceite de oliva", "2 cucharadas de vinagre balsámico", "un puñado de hierbas frescas (p. ej., perejil, albahaca)", "pimienta negra recién molida"],
 ["Precaliente el horno a 220 ºC (gas 7).", "Ponga el trigo bulgur en un tazón y vierta suficiente agua hirviendo para cubrirlo unos 1 cm. Deje remojar 30 minutos y luego escurra el exceso de líquido.", "Mientras tanto, coloque los tomates en una bandeja para hornear junto con los pimientos y ase de 10 a 15 minutos, hasta que se ablanden.", "Mezcle con cuidado el trigo bulgur con el resto de los ingredientes y sazone bien."],
 ["Para una versión sin gluten, use quinoa en lugar de trigo bulgur.", "También queda muy bien servida tibia con un tajín de garbanzos, pollo o cordero.", "Instrucciones para congelar: Se puede congelar una vez cocida. Descongele en el refrigerador o en el microondas para servir, o recaliente en el horno o en el microondas."]),
("سلطة البرغل بالطماطم والفلفل المشوي",
 "يُعدّ البرغل أساسًا رائعًا للسلطات وهو سريع وبسيط التحضير.",
 ["100 غرام من البرغل", "450 غرامًا من الطماطم الكرزية", "1 حبة فلفل رومي أحمر، مقطعة قطعًا", "2 ملعقة كبيرة من زيت الزيتون", "2 ملعقة كبيرة من خل البلسميك", "حفنة من الأعشاب الطازجة (مثل البقدونس والريحان)", "فلفل أسود مطحون طازجًا"],
 ["سخّن الفرن مسبقًا إلى 220° مئوية (علامة الغاز 7).", "ضع البرغل في وعاء واسكب عليه ما يكفي من الماء المغلي ليغمره بنحو 1 سم. اتركه ينقع 30 دقيقة، ثم صفِّ السائل الزائد.", "في الأثناء، ضع الطماطم على صينية خبز مع الفلفل الرومي وحمّصها من 10 إلى 15 دقيقة حتى تلين.", "قلّب البرغل برفق مع بقية المكونات وتبّل جيدًا."],
 ["للحصول على نسخة خالية من الغلوتين، استخدم الكينوا بدلًا من البرغل.", "وهي رائعة أيضًا عند تقديمها دافئة مع طاجن الحمص أو الدجاج أو لحم الضأن.", "تعليمات التجميد: تصلح للتجميد بعد الطهي. أذبها في الثلاجة أو المايكرويف للتقديم، أو أعد تسخينها في الفرن أو المايكرويف."])))
R.append((7700186,
("Pad Thai",
 "Fideos y verduras salteados con un sabor picante y ligeramente dulce.",
 ["250 g de fideos de arroz secos", "2 cucharaditas de aceite de colza", "6 cebollas verdes, picadas en diagonal en trozos de 1 cm", "3 dientes de ajo, machacados", "3 cm de jengibre fresco, rallado", "1 chile tailandés, en rodajas finas", "1 pimiento rojo, finamente picado", "1 calabacín, cortado en bastones", "100 g de habas congeladas", "100 g de pak choi baby, con las hojas separadas", "200 g de brotes de soya", "75 g de piña en lata en su jugo, escurrida y picada en trozos pequeños", "1 cucharada de salsa de soya sin gluten, reducida en sal", "jugo de 1 lima", "15 g de cilantro picado", "50 g de cacahuates sin sal, picados grueso y tostados", "1 lima cortada en gajos"],
 ["Cocine los fideos según las instrucciones del paquete, unos 3 a 5 minutos. Introdúzcalos en agua fría, escurra y reserve.", "Caliente el aceite en una olla grande o wok. Añada las cebollas verdes y saltee 3 minutos. Añada el ajo, el jengibre y el chile y saltee otros 2 minutos.", "Añada el pimiento rojo y el calabacín, saltee otro minuto, añada las habas y el pak choi. Saltee 1 minuto.", "Añada los fideos, saltee 2 minutos y añada los brotes de soya, la piña, la salsa de soya y el jugo de lima. Saltee 2 minutos más y añada el cilantro.", "Ponga en un tazón y cubra con los cacahuates y los gajos de lima."],
 ["Como acompañamiento, corte medio pepino en tiras largas con un pelador de verduras y añada hojas de cilantro fresco y un chorrito de lima.", "Para añadir más proteína a este plato, use habas de soya en lugar de habas o añada un poco de tofu."]),
("باد تاي",
 "نودلز وخضار مقلية بنكهة حارة وحلوة قليلًا.",
 ["250 غرامًا من نودلز الأرز الجافة", "2 ملعقة صغيرة من زيت اللفت (الكانولا)", "6 حبات بصل أخضر، مقطعة بزاوية إلى قطع بطول 1 سم", "3 فصوص ثوم، مهروسة", "3 سم من الزنجبيل الطازج، مبشورًا", "1 حبة فلفل حار تايلاندي، مقطعة شرائح رفيعة", "1 حبة فلفل رومي أحمر، مفرومة ناعمًا", "1 كوسا، مقطعة أعوادًا", "100 غرام من الفول المجمد", "100 غرام من الباك تشوي الصغير، مع فصل الأوراق", "200 غرام من نبتة الفاصولياء (براعم الفول)", "75 غرامًا من الأناناس المعلب في عصيره، مصفّى ومقطعًا قطعًا صغيرة", "1 ملعقة كبيرة من صلصة الصويا الخالية من الغلوتين وقليلة الملح", "عصير 1 ليمونة خضراء", "15 غرامًا من الكزبرة الخضراء المفرومة", "50 غرامًا من الفول السوداني غير المملح، مفرومًا فرمًا خشنًا ومحمصًا", "1 ليمونة خضراء مقطعة أرباعًا"],
 ["اسلق النودلز حسب تعليمات العبوة، حوالي 3 إلى 5 دقائق. ضعها في ماء بارد وصفِّها واتركها جانبًا.", "سخّن الزيت في قدر كبيرة أو ووك. أضف البصل الأخضر وقلّب 3 دقائق. أضف الثوم والزنجبيل والفلفل الحار وقلّب دقيقتين إضافيتين.", "أضف الفلفل الرومي الأحمر والكوسا وقلّب دقيقة إضافية، ثم أضف الفول والباك تشوي. قلّب دقيقة واحدة.", "أضف النودلز وقلّب دقيقتين، ثم أضف نبتة الفاصولياء والأناناس وصلصة الصويا وعصير الليمون الأخضر. قلّب دقيقتين إضافيتين ثم أضف الكزبرة الخضراء.", "ضعها في وعاء وزيّنها بالفول السوداني وأرباع الليمون الأخضر."],
 ["كطبق جانبي، قطّع نصف خيارة إلى شرائح طويلة بقشارة الخضار وأضف أوراق الكزبرة الخضراء الطازجة وقليلًا من عصير الليمون الأخضر.", "لإضافة المزيد من البروتين إلى هذا الطبق، استخدم فول الصويا بدلًا من الفول أو أضف بعض التوفو."])))
R.append((7705270,
("Posset de frutos rojos de verano",
 "Este elegante postre es sencillo de preparar y una celebración perfecta de las frutas del bosque de verano.",
 ["100 g de frambuesas", "100 g de arándanos azules, reservando 4 para decorar", "2 cucharadas de mermelada de fresa reducida en azúcar", "300 g de yogur natural bajo en grasa", "100 g de crème fraîche semidescremada"],
 ["Añada las frambuesas y los arándanos a la mermelada, aplaste con un tenedor y mezcle bien.", "Añada la mitad de la mezcla de frutas al yogur y a la crème fraîche, y mezcle bien.", "Reparta el resto de la mezcla de frutas entre cuatro copas, colocando una cucharada en el fondo de cada una y rociando un poco por el interior.", "Reparta la mezcla de yogur entre las copas y cubra cada una con un arándano."],
 ["Como variación, pruebe con albaricoques (chabacanos) frescos y mermelada de albaricoque, o añada un toque crujiente con un puñado de almendras tostadas o avellanas picadas.", "La crème fraîche semidescremada tiene menos de un tercio de la grasa de la crema para batir y además contiene más proteína.", "Las frutas del bosque contienen antioxidantes y vitaminas, especialmente vitamina C. Los pigmentos que les dan sus distintos colores contienen fitonutrientes y flavonoides. Son una buena fuente de fibra."]),
("بوسيت التوت الصيفي",
 "هذه الحلوى الأنيقة سهلة التحضير وهي احتفاء مثالي بتوت الصيف.",
 ["100 غرام من التوت الأحمر (الراسبيري)", "100 غرام من التوت الأزرق، مع الاحتفاظ بـ 4 حبات للتزيين", "2 ملعقة كبيرة من مربى الفراولة المخفض السكر", "300 غرام من الزبادي الطبيعي قليل الدسم", "100 غرام من الكريمة الحامضة (كريم فريش) نصف الدسمة"],
 ["أضف التوت الأحمر والتوت الأزرق إلى المربى، واهرسها بالشوكة واخلط جيدًا.", "أضف نصف خليط التوت إلى الزبادي والكريمة الحامضة، واخلط جيدًا.", "وزّع بقية خليط التوت على أربعة أكواب، مع وضع كومة صغيرة في قاع كل كوب ورش قليل منه على الجدار الداخلي.", "وزّع خليط الزبادي على الأكواب وزيّن كل كوب بحبة توت أزرق."],
 ["للتنويع، جرّب استخدام المشمش الطازج ومربى المشمش، أو أضف قرمشة برشّ اللوز المحمص أو البندق المفروم.", "تحتوي الكريمة الحامضة نصف الدسمة على أقل من ثلث دهون الكريمة الثقيلة كما تحتوي على بروتين أكثر.", "يحتوي التوت على مضادات الأكسدة والفيتامينات، وخاصة فيتامين C. وتحتوي الأصباغ التي تمنحه ألوانه المختلفة على مغذيات نباتية وفلافونويدات. وهو مصدر جيد للألياف."])))
R.append((7709454,
("Cordero a la provenzal",
 "Una receta de sabor intenso que aprovecha al máximo el cordero jugoso y tierno. Perfecta para un almuerzo de domingo.",
 ["2 cucharaditas de aceite de colza", "2 cebollas, picadas", "1 pimiento rojo, 1 amarillo y 1 verde, picados en trozos grandes", "de 4 a 6 dientes de ajo, machacados", "de 2 a 3 calabacines", "1 ramita de romero", "1 ramita de tomillo", "1 cucharadita de orégano seco", "20 g de perejil fresco picado", "1 lata de 400 g de tomates picados", "400 g de bistecs magros de cordero (100 g cada uno)"],
 ["Ponga el aceite en una olla grande. Añada las cebollas y revuelva 2 minutos a fuego medio. Luego añada los pimientos rojo, amarillo y verde y revuelva 2 minutos más. Añada el ajo y los calabacines y revuelva de 2 a 3 minutos.", "Añada el romero, el tomillo, el orégano y el perejil a las verduras y luego incorpore los tomates. Tape y cocine a fuego lento durante 10 minutos, revolviendo de vez en cuando.", "Mientras tanto, ase los bistecs de cordero al grill hasta que estén bien cocidos.", "Retire la carne del calor, tape y deje reposar 3 minutos. Sirva con la salsa provenzal y una ensalada verde."],
 ["La salsa provenzal de este plato queda bien con cualquier carne, como bistecs de cerdo o escalopes de pavo, o con pescado a la parrilla."]),
("لحم الضأن على الطريقة البروفنسالية",
 "وصفة مكثفة النكهة تُبرز أفضل ما في لحم الضأن الطري والغني بالعصارة. مثالية لغداء الأحد.",
 ["2 ملعقة صغيرة من زيت اللفت (الكانولا)", "2 بصلة، مفرومة", "1 حبة فلفل رومي أحمر و1 أصفر و1 أخضر، مقطعة قطعًا كبيرة", "من 4 إلى 6 فصوص ثوم، مهروسة", "من 2 إلى 3 كوسا", "1 غصن إكليل الجبل (روزماري)", "1 غصن زعتر", "1 ملعقة صغيرة من الأوريغانو المجفف", "20 غرامًا من البقدونس الطازج المفروم", "1 علبة طماطم مفرومة 400 غرام", "400 غرام من شرائح لحم الضأن الخالية من الدهن (100 غرام لكل شريحة)"],
 ["ضع الزيت في قدر كبيرة. أضف البصل وقلّب دقيقتين على نار متوسطة. بعد ذلك أضف الفلفل الرومي الأحمر والأصفر والأخضر وقلّب دقيقتين إضافيتين. أضف الثوم والكوسا وقلّب من 2 إلى 3 دقائق.", "أضف إكليل الجبل والزعتر والأوريغانو والبقدونس إلى الخضار، ثم أضف الطماطم وقلّب. غطِّ القدر واتركها على نار هادئة 10 دقائق مع التحريك من حين لآخر.", "في الأثناء، اشوِ شرائح لحم الضأن على الشواية حتى تنضج تمامًا.", "ارفع اللحم عن النار وغطِّه واتركه يرتاح 3 دقائق. قدّمه مع الصلصة البروفنسالية وسلطة خضراء."],
 ["تناسب الصلصة البروفنسالية لهذا الطبق أي لحم، مثل شرائح لحم الخنزير أو شرائح الديك الرومي، أو السمك المشوي."])))
R.append((7714393,
("Ensalada niçoise",
 "Una receta clásica francesa; el atún es una excelente fuente de proteína y bajo en grasa.",
 ["250 g de papas nuevas, cortadas en trozos grandes", "100 g de ejotes delgados, cocidos", "1 huevo, en cuartos", "2 tomates, cortados en gajos", "9 aceitunas negras sin hueso", "3 filetes de anchoa, partidos por la mitad a lo largo", "ralladura y jugo de 1 limón", "2 cucharaditas de aceite de oliva", "1 trozo de 150 g de atún fresco", "pimienta negra recién molida"],
 ["Hierva las papas de 15 a 20 minutos, hasta que estén apenas tiernas, y luego enfríe con agua fría.", "En un tazón, mezcle las papas, los ejotes, el huevo, los tomates, las aceitunas y las anchoas. Rocíe con la ralladura y el jugo de limón, revuelva y reserve 10 minutos.", "Caliente una sartén o plancha acanalada hasta que esté muy caliente, frote el aceite sobre el atún y selle de 2 a 3 minutos por cada lado. Deje enfriar unos minutos y luego corte en rebanadas gruesas.", "Acomode la ensalada en un platón, sazone y cubra con el atún."],
 ["Los grupos \"de riesgo\", como los bebés, los niños, las mujeres embarazadas, los adultos mayores y las personas enfermas, deben evitar comer pescado listo para consumir, ahumado en frío o curado. Por lo tanto, esta receta no es adecuada si usted pertenece a alguno de estos grupos.", "Esta receta también queda bien con salmón escalfado desmenuzado en lugar de atún.", "Si no le gustan las anchoas, añada en su lugar unos cuantos tomates secos finamente rebanados.", "Puede prepararla con huevos de codorniz cocidos, que se venden ya cocidos.", "El atún sellado no es del gusto de todos y puede no ser adecuado, así que quizá prefiera dejarlo más tiempo en la plancha, hasta que esté bien cocido."]),
("سلطة نيسواز",
 "وصفة فرنسية كلاسيكية، والتونة مصدر ممتاز للبروتين وقليلة الدهون.",
 ["250 غرامًا من البطاطس الجديدة، مقطعة قطعًا كبيرة", "100 غرام من الفاصوليا الخضراء الرفيعة، مطبوخة", "1 بيضة، مقطعة أرباعًا", "2 حبة طماطم، مقطعة أرباعًا", "9 حبات زيتون أسود منزوعة النوى", "3 فيليه أنشوجة، مقسومة إلى نصفين بالطول", "قشر وعصير 1 ليمونة مبشور", "2 ملعقة صغيرة من زيت الزيتون", "1 قطعة تونة طازجة 150 غرامًا", "فلفل أسود مطحون طازجًا"],
 ["اسلق البطاطس من 15 إلى 20 دقيقة حتى تلين بالكاد، ثم انقعها في ماء بارد لتبرد.", "في وعاء، قلّب البطاطس والفاصوليا والبيض والطماطم والزيتون والأنشوجة معًا. اسكب فوقها قشر الليمون وعصيره، وقلّب واتركها جانبًا 10 دقائق.", "سخّن مقلاة أو مقلاة مضلعة حتى تسخن جيدًا، ودلّك التونة بالزيت وحمّرها من 2 إلى 3 دقائق على كل جانب. اتركها تبرد بضع دقائق ثم قطّعها شرائح سميكة.", "رتّب السلطة في طبق كبير وتبّل وضع التونة فوقها."],
 ["ينبغي للفئات \"المعرضة للخطر\" مثل الرضع والأطفال والحوامل وكبار السن والمرضى تجنب تناول الأسماك الجاهزة للأكل أو المدخنة على البارد أو المملحة. لذلك فإن هذه الوصفة غير مناسبة إذا كنت من هذه الفئات.", "تصلح هذه الوصفة أيضًا مع السلمون المسلوق المفتّت بدلًا من التونة.", "إذا كنت لا تحب الأنشوجة، فأضف بدلًا منها بضع حبات من الطماطم المجففة مقطعة شرائح رفيعة.", "يمكنك تحضيرها ببيض السمان المسلوق، وهو متوفر مطبوخًا جاهزًا.", "التونة المحمّرة ليست مناسبة لذوق الجميع وقد لا تناسب الجميع، لذا قد ترغب في تركها على المقلاة وقتًا أطول حتى تنضج تمامًا."])))
R.append((7716059,
("Lasaña vegetariana",
 "Cocinar y armar una lasaña puede ser laborioso. Esta receta ahorra tiempo, pero ofrece sabor. También la hicimos económica.",
 ["1 cucharada de aceite de oliva", "2 cebollas medianas, peladas y finamente picadas", "3 dientes de ajo, pelados y finamente picados", "2 cucharadas de puré de tomate", "3 latas de 400 g de tomates picados", "250 g de col blanca", "2 puñados de albahaca seca, con las hojas separadas y picadas grueso", "75 g de lentejas verdes enlatadas en agua", "250 g de crème fraîche semidescremada", "250 g de láminas de lasaña integral", "50 g de queso Cheddar semidescremado rallado"],
 ["Precaliente el horno a 200 °C / 400 °F (gas 6). Para preparar la salsa de tomate, caliente el aceite en una olla grande y saltee las cebollas, el ajo y el puré de tomate a fuego medio, revolviendo, durante un par de minutos.", "Añada los tomates, enjuagando las latas con un poco de agua adicional para incorporarla a la salsa. Cocine a fuego lento 20 minutos.", "Deseche el tallo grueso de la col y pique grueso las hojas. Añádalas a la salsa junto con la albahaca y cocine a fuego lento 5 minutos; luego incorpore las lentejas y la crème fraîche, y retire del fuego.", "Ponga una capa fina de la salsa de tomate en el fondo de una bandeja para hornear de 20 cm x 30 cm.", "Añada una capa de láminas de lasaña, luego una capa de salsa de tomate y un poco de queso rallado. Continúe con láminas de lasaña y repita las capas hasta que se acaben las láminas y la salsa. Debe quedar una última capa de salsa con queso encima.", "Hornee de 30 a 40 minutos, o hasta que la lasaña esté dorada y las láminas estén blandas. Sirva con una ensalada grande."],
 ["Para una versión baja en carbohidratos de este plato, use rebanadas de berenjena en lugar de las láminas de lasaña."]),
("لازانيا نباتية",
 "قد يكون طهي اللازانيا وتجميعها مرهقًا. توفر هذه الوصفة الوقت لكنها تقدم نكهة رائعة. وجعلناها أيضًا اقتصادية.",
 ["1 ملعقة كبيرة من زيت الزيتون", "2 بصلة متوسطة الحجم، مقشرة ومفرومة ناعمًا", "3 فصوص ثوم، مقشرة ومفرومة ناعمًا", "2 ملعقة كبيرة من معجون الطماطم", "3 علب طماطم مفرومة 400 غرام", "250 غرامًا من الملفوف الأبيض", "2 حفنة من الريحان المجفف، مع فصل الأوراق وفرمها فرمًا خشنًا", "75 غرامًا من العدس الأخضر المعلب في الماء", "250 غرامًا من الكريمة الحامضة (كريم فريش) نصف الدسمة", "250 غرامًا من رقائق اللازانيا من الحبوب الكاملة", "50 غرامًا من جبن الشيدر نصف الدسم المبشور"],
 ["سخّن الفرن مسبقًا إلى 200° مئوية/400° فهرنهايت (علامة الغاز 6). لتحضير صلصة الطماطم، سخّن الزيت في قدر كبيرة وقلّب البصل والثوم ومعجون الطماطم على نار متوسطة مع التحريك لمدة دقيقتين تقريبًا.", "أضف الطماطم، مع شطف العلب بقليل من الماء الإضافي وإضافته إلى الصلصة. اتركها على نار هادئة 20 دقيقة.", "تخلّص من الساق السميكة للملفوف وافرم الأوراق فرمًا خشنًا. أضفها إلى الصلصة مع الريحان واتركها على نار هادئة 5 دقائق، ثم أضف العدس والكريمة الحامضة وقلّب برفق، وارفعها عن النار.", "ضع طبقة رقيقة من صلصة الطماطم في قاع صينية خبز بحجم 20 سم × 30 سم.", "أضف طبقة من رقائق اللازانيا، ثم طبقة من صلصة الطماطم ورشة من الجبن المبشور. تابع بطبقات رقائق اللازانيا وكرر الطبقات حتى تنفد الرقائق والصلصة. يجب أن تكون الطبقة الأخيرة من الصلصة مع الجبن في الأعلى.", "ضعها في الفرن واخبزها من 30 إلى 40 دقيقة، أو حتى تصبح اللازانيا ذهبية وتلين الرقائق. قدّمها مع سلطة كبيرة."],
 ["للحصول على نسخة أقل كربوهيدرات من هذا الطبق، استخدم شرائح الباذنجان بدلًا من رقائق اللازانيا."])))
build(4, R)
